#include <stdio.h>

#define MAXN 200005

int N, M;
long long bit_a[MAXN + 2];
long long bit_b[MAXN + 2];

static inline void add_a(int idx, long long val) {
    for (; idx <= N + 1; idx += idx & -idx) {
        bit_a[idx] += val;
    }
}

static inline void add_b(int idx, long long val) {
    for (; idx <= N + 1; idx += idx & -idx) {
        bit_b[idx] += val;
    }
}

static inline long long query_a(int idx) {
    long long sum = 0;
    for (; idx > 0; idx -= idx & -idx) {
        sum += bit_a[idx];
    }
    return sum;
}

static inline long long query_b(int idx) {
    long long sum = 0;
    for (; idx > 0; idx -= idx & -idx) {
        sum += bit_b[idx];
    }
    return sum;
}

int main() {
    if (scanf("%d %d", &N, &M) != 2) return 0;

    for (int k = 0; k < M; k++) {
        int type;
        if (scanf("%d", &type) != 1) break;

        if (type == 1) {
            long long i, v;
            scanf("%lld %lld", &i, &v);
            long long L = i;
            long long R = i + v - 1;
            if (R > N) R = N;

            // Adiciona (v + i) - x = -1 * x + (v + i)
            long long A = -1;
            long long B = v + i;

            add_a(L, A);
            add_a(R + 1, -A);
            add_b(L, B);
            add_b(R + 1, -B);
        } else if (type == 2) {
            long long i, v;
            scanf("%lld %lld", &i, &v);
            long long L = i - v + 1;
            if (L < 1) L = 1;
            long long R = i;

            // Adiciona (v - i) + x = 1 * x + (v - i)
            long long A = 1;
            long long B = v - i;

            add_a(L, A);
            add_a(R + 1, -A);
            add_b(L, B);
            add_b(R + 1, -B);
        } else if (type == 3) {
            int i;
            scanf("%d", &i);
            long long a = query_a(i);
            long long b = query_b(i);
            long long ans = a * i + b;
            printf("%lld\n", ans);
        }
    }

    return 0;
}
