#include <stdio.h>

#define MAXN 200005

int N, M;
long long bitA[MAXN];
long long bitB[MAXN];

static inline void add(long long *bit, int idx, long long val) {
    for (; idx <= N + 1; idx += idx & -idx) {
        bit[idx] += val;
    }
}

static inline void range_add(long long *bit, int l, int r, long long val) {
    if (l > r) return;
    add(bit, l, val);
    add(bit, r + 1, -val);
}

static inline long long query(long long *bit, int idx) {
    long long sum = 0;
    for (; idx > 0; idx -= idx & -idx) {
        sum += bit[idx];
    }
    return sum;
}

int main() {
    if (scanf("%d %d", &N, &M) != 2) return 0;

    for (int k = 0; k < M; ++k) {
        int type;
        scanf("%d", &type);
        if (type == 1) {
            long long i, v;
            scanf("%lld %lld", &i, &v);
            long long l = i;
            long long r = i + v - 1;
            if (r > N) r = N;

            // Adiciona: -1 * j + (v + i)
            range_add(bitA, (int)l, (int)r, -1);
            range_add(bitB, (int)l, (int)r, v + i);
        } else if (type == 2) {
            long long i, v;
            scanf("%lld %lld", &i, &v);
            long long l = i - v + 1;
            if (l < 1) l = 1;
            long long r = i;

            // Adiciona: 1 * j + (v - i)
            range_add(bitA, (int)l, (int)r, 1);
            range_add(bitB, (int)l, (int)r, v - i);
        } else if (type == 3) {
            int p;
            scanf("%d", &p);
            long long a = query(bitA, p);
            long long b = query(bitB, p);
            long long ans = a * p + b;
            printf("%lld\n", ans);
        }
    }

    return 0;
}
